def get_occupied_gpus() -> dict[tuple[str, str], tuple[str, str]]:
    """Build (server, gpu_id) → (exp_id, project) mapping from all registries.

    Only includes RUNNING / ALLOCATED / QUEUED experiments that have server + gpu set.
    Uses a short TTL cache to avoid scanning all registries on every request.
    Thread-safe via _exp_map_lock.
    """
    global _exp_map_cache

    with _exp_map_lock:
        now = time.monotonic()
        if now - _exp_map_cache[0] < _EXP_MAP_TTL:
            return _exp_map_cache[1]

    # Scan outside lock (IO-heavy), then update cache under lock
    mapping: dict[tuple[str, str], tuple[str, str]] = {}
    try:
        from core.tools.registry import _read_registry_file, get_registry_path
        from core.tools.workspace import list_workspace_projects

        projects_result = list_workspace_projects()
        if not projects_result.success:
            return mapping
        for proj in projects_result.data.get("projects", []):
            proj_name = proj["name"]
            reg_path = get_registry_path(proj_name)
            if not reg_path.exists():
                continue
            data = _read_registry_file(reg_path)
            for exp_id, exp in data.get("experiments", {}).items():
                if exp.get("status") not in ("RUNNING", "ALLOCATED", "QUEUED"):
                    continue
                server = exp.get("server")
                gpu_str = exp.get("gpu")
                if not server or not gpu_str:
                    continue
                for gpu_id in gpu_str.split(","):
                    gpu_id = gpu_id.strip()
                    if gpu_id:
                        mapping[(server, gpu_id)] = (exp_id, proj_name)
    except Exception as e:
        logger.warning("Failed to build GPU-experiment mapping: %s", e)

    with _exp_map_lock:
        _exp_map_cache = (time.monotonic(), mapping)
    return mapping


def invalidate_gpu_cache() -> None:
    """Force next call to get_occupied_gpus() to rescan registries."""
